  // Removed applyActualMessageVisibility_ACU function

  function updateApiModeView_ACU(apiMode) {
    if (!$popupInstance_ACU) return;
    const $customApiBlock = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-custom-api-settings-block`);
    const $tavernApiBlock = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-tavern-api-profile-block`);

    if (apiMode === 'tavern') {
        $customApiBlock.hide();
        $tavernApiBlock.show();
        loadTavernApiProfiles_ACU();
    } else { // custom
        $customApiBlock.show();
        $tavernApiBlock.hide();
    }
  }

  function updateCustomApiInputsState_ACU() {
    if (!$popupInstance_ACU) return;
    const useMainApi = settings_ACU.apiConfig.useMainApi;
    const $customApiFields = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-custom-api-fields`);
    if (useMainApi) {
        $customApiFields.css('opacity', '0.5');
        $customApiFields.find('input, select, button').prop('disabled', true);
    } else {
        $customApiFields.css('opacity', '1.0');
        $customApiFields.find('input, select, button').prop('disabled', false);
    }
  }

  async function loadTavernApiProfiles_ACU() {
    if (!$popupInstance_ACU) return;
    const $select = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-tavern-api-profile-select`);
    const currentProfileId = settings_ACU.tavernProfile;
    
    $select.empty().append('<option value="">-- 請選擇一個酒館預設 --</option>');

    try {
        const tavernProfiles = SillyTavern_API_ACU.extensionSettings?.connectionManager?.profiles || [];
        if (!tavernProfiles || tavernProfiles.length === 0) {
            $select.append($('<option>', { value: '', text: '未找到酒館預設', disabled: true }));
            return;
        }

        let foundCurrentProfile = false;
        tavernProfiles.forEach(profile => {
            if (profile.api && profile.preset) { // Ensure it's a valid API profile
                const option = $('<option>', {
                    value: profile.id,
                    text: profile.name || profile.id,
                    selected: profile.id === currentProfileId
                });
                $select.append(option);
                if (profile.id === currentProfileId) {
                    foundCurrentProfile = true;
                }
            }
        });

        if (currentProfileId && foundCurrentProfile) {
             $select.val(currentProfileId);
        }

    } catch (error) {
        logError_ACU('加載酒館API預設失敗:', error);
        showToastr_ACU('error', '無法加載酒館API預設列表。');
    }
  }

  function saveApiConfig_ACU() {
    if (!$popupInstance_ACU || !$customApiUrlInput_ACU || !$customApiKeyInput_ACU || !$customApiModelInput_ACU) {
      logError_ACU('保存API配置失敗：UI元素未初始化。');
      return;
    }
    const url = $customApiUrlInput_ACU.val().trim();
    const apiKey = $customApiKeyInput_ACU.val();
    const model = $customApiModelInput_ACU.val().trim();
    const max_tokens = parseInt($maxTokensInput_ACU.val(), 10);
    const temperature = parseFloat($temperatureInput_ACU.val());


    if (!url) {
      showToastr_ACU('warning', 'API URL 不能爲空。');
      return;
    }
    if (!model) {
      showToastr_ACU('warning', '請輸入或選擇一個模型。');
      return;
    }

    Object.assign(settings_ACU.apiConfig, {
        url,
        apiKey,
        model,
        max_tokens: isNaN(max_tokens) ? 120000 : max_tokens,
        temperature: isNaN(temperature) ? 0.9 : temperature,
    });
    // 將新保存的模型添加到select中（如果不存在）
    if ($customApiModelSelect_ACU && $customApiModelSelect_ACU.find(`option[value="${escapeHtml_ACU(model)}"]`).length === 0) {
        $customApiModelSelect_ACU.append(`<option value="${escapeHtml_ACU(model)}">${escapeHtml_ACU(model)}</option>`);
    }
    const selectedPresetName = $popupInstance_ACU && $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-api-preset-select`).val();
    if (selectedPresetName) {
      const preset = settings_ACU.apiPresets.find(p => p.name === selectedPresetName);
      if (preset) {
        preset.apiConfig = JSON.parse(JSON.stringify(settings_ACU.apiConfig));
        preset.apiMode = settings_ACU.apiMode;
        preset.tavernProfile = settings_ACU.tavernProfile;
      }
    }
    saveSettings_ACU();
    showToastr_ACU('success', 'API配置已套用！');
    loadSettings_ACU();
    checkApiConfigDirty_ACU();
  }

  function checkApiConfigDirty_ACU() {
    if (!$saveApiConfigButton_ACU || !$saveApiConfigButton_ACU.length) return;
    if (!$customApiUrlInput_ACU || !$customApiUrlInput_ACU.length) return;
    const cfg = settings_ACU.apiConfig || {};
    const formUrl = ($customApiUrlInput_ACU.val() || '').trim();
    const formModel = ($customApiModelInput_ACU.val() || '').trim();
    const formKey = $customApiKeyInput_ACU.val() || '';
    const formTokens = parseInt($maxTokensInput_ACU.val(), 10);
    const formTemp = parseFloat($temperatureInput_ACU.val());
    const dirty =
      formUrl !== (cfg.url || '') ||
      formModel !== (cfg.model || '') ||
      formKey !== (cfg.apiKey || '') ||
      formTokens !== (isNaN(cfg.max_tokens) ? 120000 : cfg.max_tokens) ||
      formTemp !== (isNaN(cfg.temperature) ? 0.9 : cfg.temperature);
    logDebug_ACU(`[API Dirty Check] dirty=${dirty}, formModel="${formModel}" vs saved="${cfg.model}", formTemp=${formTemp} vs saved=${cfg.temperature}`);
    $saveApiConfigButton_ACU.toggleClass('acu-api-unsaved', dirty);
  }

  function clearApiConfig_ACU() {
    Object.assign(settings_ACU.apiConfig, { url: '', apiKey: '', model: '', max_tokens: 120000, temperature: 0.9 });
    saveSettings_ACU();
    showToastr_ACU('info', 'API配置已清除！');
    loadSettings_ACU();
    checkApiConfigDirty_ACU();
  }

  // --- [新增] API預設管理函數 ---
  // 表格只保存穩定 ID，改名不斷鏈，刪除後也不會誤用同名的新預設。
  function ensureTableApiPresetIds_ACU() {
    let changed = false;
    (settings_ACU.apiPresets || []).forEach(preset => {
      if (!preset.id) {
        preset.id = `acu_api_${Date.now().toString(36)}_${Math.random().toString(36).slice(2)}`;
        changed = true;
      }
    });
    if (changed) saveSettings_ACU();
    return settings_ACU.apiPresets || [];
  }

  function getTableApiPresetId_ACU(table) {
    return String(table?.updateConfig?.apiPresetId || '').trim();
  }

  function isTableApiConfigReady_ACU(config) {
    const api = config?.apiConfig || {};
    return !!((config?.apiMode === 'tavern' && config.tavernProfile)
      || (config?.apiMode === 'custom' && (api.useMainApi || (api.url && api.model))));
  }

  function hasTableApiConfiguration_ACU() {
    return isTableApiConfigReady_ACU(settings_ACU)
      || (settings_ACU.apiPresets || []).some(isTableApiConfigReady_ACU);
  }

  function resolveTableApiConfig_ACU(presetId) {
    const preset = presetId ? (settings_ACU.apiPresets || []).find(item => item.id === presetId) : null;
    if (presetId && !preset) throw new Error('指定的 API 預設已刪除或不存在，請在表格設定重新選擇。');
    const config = preset || settings_ACU;
    if (!isTableApiConfigReady_ACU(config)) throw new Error(`API 配置不完整：${preset?.name || '目前設定'}`);
    return {
      apiMode: config.apiMode,
      apiConfig: JSON.parse(JSON.stringify(config.apiConfig || {})),
      tavernProfile: config.tavernProfile || '',
      presetName: preset?.name || '目前設定',
    };
  }

  function buildTableApiPresetOptions_ACU(updateConfig = {}) {
    const presets = ensureTableApiPresetIds_ACU();
    const selectedId = String(updateConfig.apiPresetId || '');
    let html = `<option value=""${!selectedId ? ' selected' : ''}>跟隨「API & 連接」目前設定</option>`;
    presets.forEach(preset => {
      const model = preset.apiMode === 'tavern' ? '酒館連接預設'
        : (preset.apiConfig?.useMainApi ? '主 API' : (preset.apiConfig?.model || '未設定模型'));
      html += `<option value="${escapeHtml_ACU(preset.id)}"${preset.id === selectedId ? ' selected' : ''}>${escapeHtml_ACU(preset.name)}（${escapeHtml_ACU(model)}）</option>`;
    });
    if (selectedId && !presets.some(preset => preset.id === selectedId)) {
      html += `<option value="${escapeHtml_ACU(selectedId)}" selected>預設已失效：${escapeHtml_ACU(updateConfig.apiPresetName || selectedId)}（暫停此表更新）</option>`;
    }
    return html;
  }

  // 共用入口涵蓋自動、手動及外部導入；每個請求使用自己的配置快照。
  async function routeTableUpdateByApi_ACU(targetSheetKeys, updateMode, requestOptions, runGroup) {
    const groups = new Map();
    const keys = targetSheetKeys || getSortedSheetKeys_ACU(currentJsonTableData_ACU);
    keys.forEach(key => {
      const table = currentJsonTableData_ACU?.[key];
      if (!table) return;
      if (isImportantMemoryTable_ACU(table) && settings_ACU?.plotSettings?.imMemoryEnabled === false) return;
      if (!targetSheetKeys) {
        const summary = isSummaryOrOutlineTable_ACU(table.name);
        if (['standard', 'auto_standard', 'manual_standard'].includes(updateMode) && summary) return;
        if (['summary', 'auto_summary', 'auto_summary_silent', 'manual_summary'].includes(updateMode) && !summary) return;
      }
      const id = getTableApiPresetId_ACU(table);
      const groupId = Number.isFinite(table.updateConfig?.groupId) ? Math.trunc(table.updateConfig.groupId) : -1;
      const keyForGroup = JSON.stringify([id, groupId]);
      if (!groups.has(keyForGroup)) groups.set(keyForGroup, { id, keys: [], names: [] });
      groups.get(keyForGroup).keys.push(key);
      groups.get(keyForGroup).names.push(table.name || key);
    });
    // 在任何 await 之前固定所有組別配置，避免執行中切換全局設定影響後續組別。
    groups.forEach(group => {
      try { group.config = resolveTableApiConfig_ACU(group.id); }
      catch (error) { group.error = error.message; }
    });
    let success = true;
    for (const group of groups.values()) {
      if (wasStoppedByUser_ACU) return false;
      if (group.error) {
        showToastr_ACU('error', `${group.names.join('、')}：${group.error}`, { acuToastCategory: ACU_TOAST_CATEGORY_ACU.ERROR });
        success = false;
        continue;
      }
      const ok = await runGroup(group.keys, {
        ...requestOptions,
        tableApiResolved: true,
        tableApiConfig: group.config,
        // 酒館預設按 ID 請求，不切換全局連接；主 API 保留跟隨語義。
        skipProfileSwitch: true,
        forceDirectApi: group.id && group.config.apiMode === 'custom' && group.config.apiConfig.useMainApi ? false : !!requestOptions?.forceDirectApi,
      });
      if (!ok) success = false;
    }
    return success;
  }

  function saveApiPreset_ACU(presetName) {
    if (!presetName || !presetName.trim()) {
      showToastr_ACU('warning', '請輸入預設名稱。');
      return false;
    }
    presetName = presetName.trim();
    
    const newPreset = {
      name: presetName,
      apiMode: settings_ACU.apiMode,
      apiConfig: JSON.parse(JSON.stringify(settings_ACU.apiConfig)),
      tavernProfile: settings_ACU.tavernProfile
    };
    
    // 檢查是否已存在同名預設
    const existingIndex = settings_ACU.apiPresets.findIndex(p => p.name === presetName);
    if (existingIndex >= 0) {
      newPreset.id = settings_ACU.apiPresets[existingIndex].id;
      settings_ACU.apiPresets[existingIndex] = newPreset;
      showToastr_ACU('success', `API預設 "${presetName}" 已更新。`);
    } else {
      settings_ACU.apiPresets.push(newPreset);
      showToastr_ACU('success', `API預設 "${presetName}" 已保存。`);
    }
    
    saveSettings_ACU();
    refreshApiPresetSelectors_ACU();
    return true;
  }

  function loadApiPreset_ACU(presetName) {
    const preset = settings_ACU.apiPresets.find(p => p.name === presetName);
    if (!preset) {
      showToastr_ACU('error', `未找到預設 "${presetName}"。`);
      return false;
    }
    
    settings_ACU.apiMode = preset.apiMode;
    settings_ACU.apiConfig = JSON.parse(JSON.stringify(preset.apiConfig));
    settings_ACU.tavernProfile = preset.tavernProfile;
    
    saveSettings_ACU();
    loadSettings_ACU();
    showToastr_ACU('success', `已加載API預設 "${presetName}"。`);
    checkApiConfigDirty_ACU();
    return true;
  }

  function renameApiPreset_ACU(oldName, newName) {
    if (!oldName || !newName || !newName.trim()) {
      showToastr_ACU('warning', '請輸入新的預設名稱。');
      return false;
    }
    newName = newName.trim();
    if (oldName === newName) return true;
    const preset = settings_ACU.apiPresets.find(p => p.name === oldName);
    if (!preset) {
      showToastr_ACU('error', `未找到預設 "${oldName}"。`);
      return false;
    }
    if (settings_ACU.apiPresets.some(p => p.name === newName)) {
      showToastr_ACU('error', `預設名稱 "${newName}" 已存在。`);
      return false;
    }
    preset.name = newName;
    if (settings_ACU.tableApiPreset === oldName) settings_ACU.tableApiPreset = newName;
    if (settings_ACU.plotApiPreset === oldName) settings_ACU.plotApiPreset = newName;
    saveSettings_ACU();
    refreshApiPresetSelectors_ACU();
    const $apiPresetSelect = $popupInstance_ACU && $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-api-preset-select`);
    if ($apiPresetSelect && $apiPresetSelect.length) $apiPresetSelect.val(newName);
    showToastr_ACU('success', `預設已重命名為 "${newName}"。`);
    return true;
  }

  function deleteApiPreset_ACU(presetName) {
    const index = settings_ACU.apiPresets.findIndex(p => p.name === presetName);
    if (index < 0) {
      showToastr_ACU('error', `未找到預設 "${presetName}"。`);
      return false;
    }
    
    settings_ACU.apiPresets.splice(index, 1);
    
    // 清除使用該預設的引用
    if (settings_ACU.tableApiPreset === presetName) {
      settings_ACU.tableApiPreset = '';
    }
    if (settings_ACU.plotApiPreset === presetName) {
      settings_ACU.plotApiPreset = '';
    }
    
    saveSettings_ACU();
    refreshApiPresetSelectors_ACU();
    showToastr_ACU('info', `API預設 "${presetName}" 已刪除。`);
    return true;
  }

  function refreshApiPresetSelectors_ACU() {
    if (!$popupInstance_ACU) return;
    
    const presets = settings_ACU.apiPresets || [];
    
    // 刷新API配置頁面的預設選擇器
    const $apiPresetSelect = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-api-preset-select`);
    if ($apiPresetSelect.length) {
      $apiPresetSelect.empty().append('<option value="">-- 選擇預設 --</option>');
      presets.forEach(p => {
        $apiPresetSelect.append(`<option value="${p.name}">${p.name}</option>`);
      });
    }
    
    // 刷新填表的API預設選擇器
    const $tableApiPresetSelect = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-table-api-preset-select`);
    if ($tableApiPresetSelect.length) {
      $tableApiPresetSelect.empty().append('<option value="">使用當前API配置</option>');
      presets.forEach(p => {
        $tableApiPresetSelect.append(`<option value="${p.name}">${p.name}</option>`);
      });
      $tableApiPresetSelect.val(settings_ACU.tableApiPreset || '');
    }
    
    // 刷新劇情推進的API預設選擇器
    const $plotApiPresetSelect = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-api-preset-select`);
    if ($plotApiPresetSelect.length) {
      $plotApiPresetSelect.empty().append('<option value="">使用當前API配置</option>');
      presets.forEach(p => {
        $plotApiPresetSelect.append(`<option value="${p.name}">${p.name}</option>`);
      });
      $plotApiPresetSelect.val(settings_ACU.plotApiPreset || '');
    }

    // 刷新正文替換的API預設選擇器
    const $optimizationApiPresetSelect = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-optimization-api-preset`);
    if ($optimizationApiPresetSelect.length) {
      $optimizationApiPresetSelect.empty().append('<option value="">使用當前API配置</option>');
      presets.forEach(p => {
        $optimizationApiPresetSelect.append(`<option value="${p.name}">${p.name}</option>`);
      });
      $optimizationApiPresetSelect.val(settings_ACU.contentOptimizationSettings?.apiPreset || '');
    }
  }

  /**
   * 根據預設名稱獲取API配置
   * @param {string} presetName - 預設名稱，空字符串表示使用當前配置
   * @returns {object} - 包含 apiMode, apiConfig, tavernProfile 的配置對象
   */
  function getApiConfigByPreset_ACU(presetName) {
    if (!presetName) {
      // 使用當前配置
      return {
        apiMode: settings_ACU.apiMode,
        apiConfig: settings_ACU.apiConfig,
        tavernProfile: settings_ACU.tavernProfile
      };
    }
    
    const preset = settings_ACU.apiPresets.find(p => p.name === presetName);
    if (preset) {
      return {
        apiMode: preset.apiMode,
        apiConfig: preset.apiConfig,
        tavernProfile: preset.tavernProfile
      };
    }
    
    // 預設不存在，回退到當前配置
    logWarn_ACU(`API預設 "${presetName}" 不存在，使用當前配置。`);
    return {
      apiMode: settings_ACU.apiMode,
      apiConfig: settings_ACU.apiConfig,
      tavernProfile: settings_ACU.tavernProfile
    };
  }

  function saveCustomCharCardPrompt_ACU() {
    if (!$popupInstance_ACU || !$charCardPromptSegmentsContainer_ACU) {
      logError_ACU('保存更新預設失敗：UI元素未初始化。');
      return;
    }
    let newPromptSegments = getCharCardPromptFromUI_ACU();
    if (!newPromptSegments || newPromptSegments.length === 0 || (newPromptSegments.length === 1 && !newPromptSegments[0].content.trim())) {
      showToastr_ACU('warning', '更新預設不能爲空。');
      return;
    }

    // [健全性] 主提示詞槽位去重：A/B 各最多一個（多餘的自動降級爲普通段落）
    try {
      const seen = { A: false, B: false };
      newPromptSegments = newPromptSegments.map(seg => {
        const slot = String(seg?.mainSlot || (seg?.isMain ? 'A' : (seg?.isMain2 ? 'B' : ''))).toUpperCase();
        if (slot === 'A' || slot === 'B') {
          if (seen[slot]) {
            const cleaned = { ...seg };
            delete cleaned.mainSlot;
            delete cleaned.isMain;
            delete cleaned.isMain2;
            cleaned.deletable = cleaned.deletable !== false;
            return cleaned;
          }
          seen[slot] = true;
        }
        return seg;
      });
    } catch (e) {}

    // 保存爲JSON數組格式
    settings_ACU.charCardPrompt = newPromptSegments;
    saveSettings_ACU();
    showToastr_ACU('success', '更新預設已保存！');
    loadSettings_ACU(); // This will re-render from the saved data.
  }

  function resetDefaultCharCardPrompt_ACU() {
    settings_ACU.charCardPrompt = DEFAULT_CHAR_CARD_PROMPT_ACU;
    saveSettings_ACU();
    showToastr_ACU('info', '更新預設已恢復爲默認值！');
    // loadSettings will trigger renderPromptSegments_ACU which correctly handles the string default
    loadSettings_ACU();
  }

  function loadCharCardPromptFromJson_ACU() {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = e => {
        const file = e.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = readerEvent => {
            const content = readerEvent.target.result;
            let jsonData;

            try {
                jsonData = JSON.parse(content);
            } catch (error) {
                logError_ACU('導入提示詞模板失敗：JSON解析錯誤。', error);
                showToastr_ACU('error', '文件不是有效的JSON格式。', { timeOut: 5000 });
                return;
            }
            
            try {
                // Basic validation: must be an array of objects with role and content
                if (!Array.isArray(jsonData) || jsonData.some(item => typeof item.role === 'undefined' || typeof item.content === 'undefined')) {
                    throw new Error('JSON格式不正確。它必須是一個包含 "role" 和 "content" 鍵的對象的數組。');
                }
                
                // Add deletable: true and normalize roles for consistency
                const segments = jsonData.map(item => {
                    let normalizedRole = 'USER'; // Default to USER
                    if (item.role) {
                        const roleLower = item.role.toLowerCase();
                        if (roleLower === 'system') {
                            normalizedRole = 'SYSTEM';
                        } else if (roleLower === 'assistant' || roleLower === 'ai') {
                            normalizedRole = 'assistant';
                        }
                    }
                    const slot = String(item?.mainSlot || (item?.isMain ? 'A' : (item?.isMain2 ? 'B' : ''))).toUpperCase();
                    const normalizedSlot = (slot === 'A' || slot === 'B') ? slot : '';
                    return {
                        ...item,
                        role: normalizedRole,
                        mainSlot: normalizedSlot || item.mainSlot,
                        // 主提示詞A/B不可刪除
                        deletable: (normalizedSlot ? false : (item.deletable !== false)),
                    };
                });

                // Use the existing render function
                renderPromptSegments_ACU(segments);
                showToastr_ACU('success', '提示詞模板已成功加載！');
                logDebug_ACU('New prompt template loaded from JSON file.');

            } catch (error) {
                logError_ACU('導入提示詞模板失敗：結構驗證失敗。', error);
                showToastr_ACU('error', `導入失敗: ${error.message}`, { timeOut: 10000 });
            }
        };
        reader.readAsText(file, 'UTF-8');
    };
    input.click();
  }

  // [新增] 導出“填表提示詞組(更新預設/AI指令預設)”爲 JSON（與 loadCharCardPromptFromJson_ACU 聯動）
  function exportCharCardPromptToJson_ACU() {
    try {
      const segments = getCharCardPromptFromUI_ACU();
      if (!Array.isArray(segments) || segments.length === 0) {
        showToastr_ACU('warning', '沒有可導出的提示詞模板。');
        return;
      }
      // 基礎校驗：必須包含 role/content
      const invalid = segments.some(s => !s || typeof s !== 'object' || typeof s.role === 'undefined' || typeof s.content === 'undefined');
      if (invalid) {
        showToastr_ACU('error', '導出失敗：提示詞結構不完整（缺少 role 或 content）。');
        return;
      }

      const jsonString = JSON.stringify(segments, null, 2);
      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'TavernDB_TablePromptGroup.json';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      showToastr_ACU('success', '提示詞模板已導出爲JSON！', { acuToastCategory: ACU_TOAST_CATEGORY_ACU.MANUAL_TABLE });
    } catch (e) {
      logError_ACU('導出提示詞模板失敗:', e);
      showToastr_ACU('error', '導出提示詞模板失敗，請檢查控制檯獲取詳情。', { acuToastCategory: ACU_TOAST_CATEGORY_ACU.ERROR });
    }
  }
